import { Component, Input, Output, EventEmitter } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { Trip } from '../../models/trip';
import { TripService } from '../../services/trip.service';

@Component({
  selector: 'app-trip-card',
  standalone: true,
  imports: [CommonModule, RouterModule],
  templateUrl: './trip-card.component.html',
  styleUrls: ['./trip-card.component.css']
})
export class TripCardComponent {
  @Input() trip!: Trip;
  @Input() showAdminActions = false;
  @Output() tripDeleted = new EventEmitter<string>();
  @Output() tripUpdated = new EventEmitter<void>();

  deleting = false;
  showDeleteConfirm = false;

  constructor(private tripService: TripService) {}

  onEdit(): void {
    // Navigation is handled by routerLink in template
  }

  onDelete(): void {
    this.showDeleteConfirm = true;
  }

  confirmDelete(): void {
    if (!this.trip._id) return;

    this.deleting = true;
    this.tripService.deleteTrip(this.trip._id).subscribe({
      next: () => {
        this.tripDeleted.emit(this.trip._id);
        this.showDeleteConfirm = false;
        this.deleting = false;
      },
      error: (error) => {
        console.error('Error deleting trip:', error);
        alert('Failed to delete trip. Please try again.');
        this.deleting = false;
        this.showDeleteConfirm = false;
      }
    });
  }

  cancelDelete(): void {
    this.showDeleteConfirm = false;
  }

  formatPrice(price: string): string {
    // Remove any existing formatting and add proper formatting
    const numericPrice = price.replace(/[^0-9.]/g, '');
    const number = parseFloat(numericPrice);
    return isNaN(number) ? price : `$${number.toLocaleString()}`;
  }

  formatDate(dateString: string): string {
    try {
      const date = new Date(dateString);
      return date.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric'
      });
    } catch {
      return dateString;
    }
  }

  getDurationBadgeClass(length: string): string {
    const days = parseInt(length.match(/\d+/)?.[0] || '0');
    if (days <= 3) return 'bg-success';
    if (days <= 7) return 'bg-warning';
    return 'bg-info';
  }

  getPriceBadgeClass(price: string): string {
    const numericPrice = parseFloat(price.replace(/[^0-9.]/g, ''));
    if (numericPrice < 1000) return 'bg-success';
    if (numericPrice < 1500) return 'bg-warning';
    return 'bg-danger';
  }

  truncateDescription(description: string, maxLength: number = 120): string {
    if (description.length <= maxLength) return description;
    return description.substring(0, maxLength).trim() + '...';
  }
}

<div class="card h-100 shadow-sm trip-card">
  <!-- Trip Image -->
  <div class="card-img-container">
    <img [src]="trip.image" 
         [alt]="trip.name" 
         class="card-img-top"
         (error)="onImageError($event)">

    <!-- Duration Badge -->
    <span class="badge position-absolute top-0 start-0 m-2" 
          [class]="getDurationBadgeClass(trip.length)">
      <i class="fas fa-clock me-1"></i>{{ trip.length }}
    </span>

    <!-- Price Badge -->
    <span class="badge position-absolute top-0 end-0 m-2" 
          [class]="getPriceBadgeClass(trip.perPerson)">
      {{ formatPrice(trip.perPerson) }}
    </span>
  </div>

  <!-- Card Body -->
  <div class="card-body d-flex flex-column">
    <!-- Trip Header -->
    <div class="trip-header mb-3">
      <h5 class="card-title fw-bold mb-1">{{ trip.name }}</h5>
      <div class="trip-meta">
        <small class="text-muted">
          <i class="fas fa-map-marker-alt me-1"></i>{{ trip.resort }}
        </small>
        <small class="text-muted ms-3">
          <i class="fas fa-calendar-alt me-1"></i>{{ formatDate(trip.start) }}
        </small>
      </div>
      <div class="trip-code mt-1">
        <span class="badge bg-light text-dark">{{ trip.code }}</span>
      </div>
    </div>

    <!-- Trip Description -->
    <div class="trip-description flex-grow-1 mb-3">
      <p class="card-text text-muted">
        {{ truncateDescription(trip.description) }}
      </p>
    </div>

    <!-- Trip Details -->
    <div class="trip-details mb-3">
      <div class="row g-2">
        <div class="col-6">
          <div class="detail-item">
            <i class="fas fa-calendar-check text-primary me-2"></i>
            <span class="fw-semibold">{{ trip.length }}</span>
          </div>
        </div>
        <div class="col-6">
          <div class="detail-item">
            <i class="fas fa-dollar-sign text-success me-2"></i>
            <span class="fw-semibold">{{ formatPrice(trip.perPerson) }}</span>
          </div>
        </div>
      </div>
    </div>

    <!-- Action Buttons -->
    <div class="card-actions mt-auto">
      <div class="d-grid gap-2" *ngIf="!showAdminActions">
        <button class="btn btn-primary">
          <i class="fas fa-info-circle me-2"></i>View Details
        </button>
      </div>

      <div class="btn-group w-100" *ngIf="showAdminActions && !showDeleteConfirm">
        <button class="btn btn-outline-primary" 
                [routerLink]="['/edit-trip', trip._id]"
                title="Edit Trip">
          <i class="fas fa-edit me-1"></i>Edit
        </button>
        <button class="btn btn-outline-danger" 
                (click)="onDelete()"
                title="Delete Trip">
          <i class="fas fa-trash me-1"></i>Delete
        </button>
      </div>

      <!-- Delete Confirmation -->
      <div *ngIf="showDeleteConfirm" class="delete-confirmation">
        <div class="alert alert-warning mb-2 py-2">
          <small>
            <i class="fas fa-exclamation-triangle me-1"></i>
            Are you sure you want to delete this trip?
          </small>
        </div>
        <div class="btn-group w-100">
          <button class="btn btn-danger btn-sm" 
                  (click)="confirmDelete()"
                  [disabled]="deleting">
            <span *ngIf="deleting" class="spinner-border spinner-border-sm me-1"></span>
            <i *ngIf="!deleting" class="fas fa-check me-1"></i>
            {{ deleting ? 'Deleting...' : 'Yes, Delete' }}
          </button>
          <button class="btn btn-secondary btn-sm" 
                  (click)="cancelDelete()"
                  [disabled]="deleting">
            <i class="fas fa-times me-1"></i>Cancel
          </button>
        </div>
      </div>
    </div>
  </div>

  <!-- Card Footer -->
  <div class="card-footer bg-transparent border-0 pt-0">
    <div class="d-flex justify-content-between align-items-center">
      <div class="rating">
        <i class="fas fa-star text-warning"></i>
        <i class="fas fa-star text-warning"></i>
        <i class="fas fa-star text-warning"></i>
        <i class="fas fa-star text-warning"></i>
        <i class="fas fa-star-half-alt text-warning"></i>
        <small class="text-muted ms-1">4.5 (128 reviews)</small>
      </div>
      <div class="availability">
        <span class="badge bg-success">
          <i class="fas fa-check-circle me-1"></i>Available
        </span>
      </div>
    </div>
  </div>
</div>
